import React from "react";

export default function About() {
  return (
    <section className="page">
      <h1>About</h1>
      <pre style={{ lineHeight: 1.5 }}>
{`O leaf and clove, unite my sleepy soul,
A kettle hums—the flatmates call me “chai.”
I stir the storm; the cup becomes my goal,
A small rebell’—to sip, to rate, to try.

Three stars today? perhaps—but hearts are wild;
Some mornings mercy tastes like cardamom.
On rainy nights I’m cinnamon’s soft child,
By dawn I’m ginger’s spark—unbothered, calm.

Log what you love; let simple rituals stay.
The world reloads; our mugs remember heat.
A line of notes can hold a stubborn day,
And sugar learns to dance with bitter, sweet.

This app is small; that’s fine—we brew, we be.
Now fetch the cup. The rest can wait for tea.`}
      </pre>
    </section>
  );
}
